    h,w=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    out=[row[:] for row in g]
    dirs=[((1,1),lambda i,j:i-j),((1,-1),lambda i,j:i+j)]
    for d,keyf in dirs:
        D={}
        for i in range(h):
            for j in range(w):
                if g[i][j]!=bg: D.setdefault(keyf(i,j),[]).append((i,j))
        for kk,ps in D.items():
            ps.sort(); groups=[];cur=[ps[0]]
            for p in ps[1:]:
                if p[0]==cur[-1][0]+1 and p[1]==cur[-1][1]+d[1]: cur.append(p)
                else: groups.append(cur);cur=[p]
            groups.append(cur)
            for run in groups:
                if len(run)<2: continue
                c=g[run[0][0]][run[0][1]]; head,tail=run[0],run[-1]
                seeds=((head,(-d[0],-d[1])),(tail,d))
                for seed,dd in seeds:
                    i,j=seed[0]+dd[0],seed[1]+dd[1]
                    while 0<=i<h and 0<=j<w and g[i][j]==bg:
                        out[i][j]=c; i+=dd[0]; j+=dd[1]
    return out
