def base(g,extra=None):
    h,w=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    out=[row[:] for row in g]
    def step_ok(i,j,c):
        if not(0<=i<h and 0<=j<w): return False
        val=g[i][j]
        if val==c: return True      # same color, walk
        if extra and extra.contains(val): return True  # transparency
        return False               # block
    cells_nonbg=[(i,j) for i in range(h) for j in range(w) if g[i][j]!=bg]
    if extra: extra.cells=set(cells_nonbg)
    for i,j in cells_nonbg:
        c=g[i][j]
        for d in dirs:
            ii,jj=i+d[0],j+d[1]
            while step_ok(ii,jj,c):
                out[ii][jj]=c; ii+=d[0]; jj+=d[1]
    return out
# variant: rays stop before becoming 8-adjacent to a different non-bg cell
def adj_stop(g):
    h,w=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    nb=[[0]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg:
                for a in range(-1,2):
                    for b in range(-1,2):
                        x,y=i+a,j+b
                        if 0<=x<h and 0<=y<w and g[x][y]!=g[i][j] and g[x][y]!=bg:
                            nb[x][y]=1
    out=[row[:] for row in g]
    for i,j in [(i,j) for i in range(h) for j in range(w) if g[i][j]!=bg]:
        c=g[i][j]
        for d in dirs:
            ii,jj=i+d[0],j+d[1]
            while 0<=ii<h and 0<=jj<w and g[ii][jj]==bg and not nb[ii][jj]:
                out[ii][jj]=c; ii+=d[0]; jj+=d[1]
    return out
