def ray_cells(g,i,j,d,limit=None):
    x,y=i+d[0],j+d[1]; res=[]
    while 0<=x<len(g) and 0<=y<len(g[0]) and (limit is None or len(res)<limit):
        v=g[x][y]
        res.append((x,y,v))
        if v!=Counter(x for r in g for x in r).most_common(1)[0][0]: break
        x+=d[0]; y+=d[1]
    return res
